Lemma aheap_pres_refill : forall L st X LB (sp : word) (sE lo : Z) m m',
  alayout_ok L -> awf L st X -> ablocks L st X LB ->
  munch (arefill_W L st K_BATCH_CLASS sE) m m' -> wmono asegs m m' ->
  ATOP <= lo -> lo <= sE - 1536 -> sE <= bv_unsigned sp ->
